-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
-- Later shawl signal banter is not restored.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("stares at you through bleary eyes. 'I get enough conversation from my wife. If ya want water or biscuits, buy em! Otherwise, leave me alone!'")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 30038, item2 = 30057 }) then
    e.self:Emote("puts a tiny eyeglass up to his eye and studies the key and chain. \"Aye, this looks like the perfect metal to fix this key. Gimmie just a moment.\" He uses fine and minute tools to pick and push the chain and key over a fire. \"Ha! Don't say I ain't never done anythin for ya.\"")
    e.other:SummonItem(30040)
  elseif item_lib.check_turn_in(e.trade, { item1 = 30037 }) then
    e.self:Emote("stares at you and then laughs before putting on the earmuffs. As he moves around, blissfully protected from the noise, a fine chain slips from his coat. 'Hey! Look at that! What a fine chain! It looks familiar but I can't tell how. Oh, well, yu can have it. It looks like it could be used to fill gaps or if needed to repair another similar metal object. I can do that if you ever find need.")
    e.other:SummonItem(30038)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25104 }) then
    e.self:Say("Uhhh, thank you... Now I can uhh... work on fixing some things around...")
    e.self:Emote("seems to nod off for a moment as he drops a small note on the ground.")
    eq.create_ground_object(20474, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading()) -- Decay uses the runtime default, not a verified P99 duration.
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
